function validateBackup(data){if(!data||typeof data!=='object'||Array.isArray(data))throw Error('Ungültige Sicherung');const result=empty(),ids={};for(const k of Object.keys(result)){if(k==='hotel')continue;if(data[k]===undefined&&['lostItems','guestWishes','maintenance','handover'].includes(k))continue;if(!Array.isArray(data[k]))throw Error('Ungültige Tabelle: '+k);ids[k]=new Set();for(const row of data[k]){if(!row||typeof row!=='object'||typeof row.id!=='string'||!row.id||ids[k].has(row.id))throw Error('Ungültige oder doppelte ID: '+k);ids[k].add(row.id)}result[k]=data[k]}if(!data.hotel||typeof data.hotel.name!=='string')throw Error('Hotelprofil fehlt');for(const k of Object.keys(result.hotel)){if(Object.prototype.hasOwnProperty.call(data.hotel,k)){if(typeof data.hotel[k]!=='string')throw Error('Ungültiges Hotelprofil: '+k);result.hotel[k]=data.hotel[k]}}const link=(k,id)=>{if(!ids[k].has(id))throw Error('Fehlende Verknüpfung: '+k)};for(const b of result.bookings){link('guests',b.guest);link('rooms',b.room);if(b.depositAmount==null&&Number(b.deposit)>0)b.depositAmount=Number(b.deposit)}for(const i of result.invoices){link('bookings',i.booking);if(!Array.isArray(i.lines)||!Number.isFinite(Number(i.total))||Number(i.total)<0)throw Error('Ungültige Rechnung');for(const key of ['credits','refunds']){if(i[key]===undefined)continue;if(!Array.isArray(i[key])||i[key].some(row=>!row||typeof row!=='object'||!Number.isFinite(Number(row.amount))||Number(row.amount)<=0))throw Error('Ungültige Rechnungsdaten: '+key)}}for(const p of result.payments){link('invoices',p.invoice);if(!Number.isFinite(Number(p.amount))||Number(p.amount)<=0)throw Error('Ungültige Zahlung')}for(const s of result.services)link('bookings',s.booking);for(const t of result.tasks)link('rooms',t.room);for(const t of result.maintenance)if(t.room)link('rooms',t.room);for(const t of result.guestWishes){if(t.room)link('rooms',t.room);if(t.guest)link('guests',t.guest)}return result}
let listPage=1,listFilters={};
function listFilterControls(k){return schemas[k][1].filter(f=>Array.isArray(f[2])).map(f=>'<label>'+esc(f[1])+'<select data-list-filter="'+esc(f[0])+'"><option value="">Alle</option>'+f[2].map(v=>'<option value="'+esc(v)+'" '+(listFilters[f[0]]===String(v)?'selected':'')+'>'+esc(v)+'</option>').join('')+'</select></label>').join('')}

function list(k){
 const matches=db[k].filter(x=>(JSON.stringify(x)+' '+label(k,x)+' '+(x.room?get('rooms',x.room).number||'':'')).toLowerCase().includes(query.toLowerCase())&&Object.keys(listFilters).every(key=>!listFilters[key]||String(x[key]??'')===listFilters[key])),size=12,total=Math.max(1,Math.ceil(matches.length/size));listPage=Math.max(1,Math.min(total,listPage));
 const markup=matches.slice((listPage-1)*size,listPage*size).map(x=>{
  if(k==='rooms')return '<div class="entry"><div><strong>Zimmer '+esc(x.number)+'</strong><small>'+esc(x.category||'')+' · ab '+money(x.rate||0)+' ohne Verpflegung</small></div><div class="room-row-actions">'+btn('Tarif prüfen','roomTariff',x.id)+btn('Bearbeiten','edit','rooms:'+x.id)+'</div></div>';
  return entry(label(k,x),schemas[k][1].map(f=>x[f[0]]).filter(Boolean).slice(1,4).join(' · '),'edit',k+':'+x.id);
 }).join('')||'<p>Keine Einträge vorhanden.</p>';
 return markup+'<div class="actions list-pagination"><small>'+matches.length+' Einträge · Seite '+listPage+' von '+total+'</small>'+(listPage>1?btn('Zurück','listPage',String(listPage-1)):'')+(listPage<total?btn('Weiter','listPage',String(listPage+1)):'')+'</div>';
}

function showRoomTariff(id){
 const room=get('rooms',id);if(!room.id)throw Error('Zimmer nicht gefunden');
 const start=today(),stop=new Date(Date.parse(start+'T12:00:00Z')+86400000).toISOString().slice(0,10);
 const markup='<h2>Zimmer '+esc(room.number)+' · Tarifvorschau</h2><p>Berechnung ohne Reservation zu speichern.</p><form id="tariff-preview-form"><label>Anreise</label><input type="date" name="arrival" value="'+esc(start)+'" required><label>Abreise</label><input type="date" name="departure" value="'+esc(stop)+'" required><label>Erwachsene</label><input type="number" name="adults" min="1" max="6" value="2" required><label>Kinder</label><input type="number" name="children" min="0" max="4" value="0" required><label>Verpflegung</label><select name="meal"><option>Nur Logis</option><option>Frühstück</option><option>Halbpension</option><option>Vollpension</option></select><div class="actions"><button class="primary" type="submit">Berechnen</button>'+btn('Schliessen','close')+'</div></form><pre id="tariff-preview-result" aria-live="polite" class="pricing-quote"></pre>';
 dialog(markup);
 $('tariff-preview-form').onsubmit=e=>{
  e.preventDefault();
  try{
   const form=Object.fromEntries(new FormData(e.target).entries());
   const q=bookingQuote(form,room,db.hotel);
   const lines=['Tarifberechnung · '+q.nights+' Nächte',q.adults+' Erwachsene, '+q.children+' Kinder'];
   q.lodgingDays.forEach(d=>lines.push(d.date+'  '+money(d.amount)));
   lines.push('Zimmer ohne Verpflegung: '+money(q.lodging));
   lines.push('Frühstück: '+money(q.breakfast));
   lines.push('Weitere Mahlzeiten: '+money(q.other));lines.push('Kurtaxe / Gästetaxe: '+money(q.touristTax||0));
   lines.push('Gesamt inkl. MWST: '+money(q.total));
   $('tariff-preview-result').textContent=lines.join('\n');
  }catch(err){$('tariff-preview-result').textContent='Berechnung nicht möglich: '+err.message}
 };
}
function dialog(s){const headingMatch=s.match(/<h[12][^>]*>([\s\S]*?)<\/h[12]>/i),title=headingMatch?headingMatch[1].replace(/<[^>]*>/g,''):'Aktion';const content=headingMatch?s.replace(headingMatch[0],''):s;const kind=/zimmer|room/i.test(title)?'Zimmerverwaltung':/gast|gäst/i.test(title)?'Gästeverwaltung':/zahlung|rechnung|mahnung/i.test(title)?'Finanzen':/reserv|buchung/i.test(title)?'Reservationen':'Hotelbetrieb';$('dialog').innerHTML='<div class="dialog-toolbar"><div class="dialog-identity"><span class="dialog-kicker">STAY Swiss · '+esc(kind)+'</span><h2 id="dialog-heading">'+esc(title)+'</h2></div>'+btn('Schliessen','close','','dialog-close')+'</div><div class="dialog-content"><div class="dialog-section-title">Details und Einstellungen</div>'+content+'</div>';$('overlay').hidden=false;$('dialog').setAttribute('aria-labelledby','dialog-heading');$('dialog').setAttribute('role','dialog');$('dialog').setAttribute('aria-modal','true')}
function close(){$('overlay').hidden=true}
