function edit(k,id){if(k==='bookings'&&!id&&window.innerWidth<800){startBooking();return}const x=get(k,id),schema=schemas[k];dialog('<h2>'+schema[0]+'</h2><form id="editor" class="compact-editor columns-'+(schema[1].length>=9?3:schema[1].length>=4?2:1)+'"><div class="editor-fields">'+schema[1].map(([key,title,type])=>{let v=x[key]!==undefined&&x[key]!==null?x[key]:(k==='bookings'&&key==='adults'?x.people||1:k==='bookings'&&['children','taxExemptAdults','taxExemptChildren','depositAmount'].includes(key)?0:k==='bookings'&&key==='meal'?'Nur Logis':k==='bookings'&&key==='status'?'Bestätigt':(type==='date'&&k==='bookings'&&key==='arrival')?today():(type==='date'&&k==='bookings'&&key==='departure')?new Date(Date.parse(today()+'T12:00:00Z')+86400000).toISOString().slice(0,10):'');let field;if(type==='country'){field=countrySelect(key,v,key==='country')}else if(Array.isArray(type)||type.startsWith('@')){let opts=Array.isArray(type)?type.map(t=>[t,t]):db[type.slice(1)].map(t=>[t.id,label(type.slice(1),t)]);if(k==='rooms'&&key==='category'&&v&&!opts.some(o=>o[0]===v))opts.unshift([v,v+' (bisherige Kategorie)']);if(k==='tasks'&&key==='name'&&v&&!opts.some(o=>o[0]===v))opts.unshift([v,v+' (bisherige Aufgabe)']);field='<select required name="'+key+'"><option value="">Auswählen</option>'+opts.map(o=>'<option value="'+esc(o[0])+'" '+(String(o[0])===String(v)?'selected':'')+'>'+esc(o[1])+'</option>').join('')+'</select>'}else if(type==='textarea')field='<textarea name="'+key+'">'+esc(v)+'</textarea>';else field='<input name="'+key+'" type="'+type+'" value="'+esc(v)+'" '+(type==='number'?'min="0" step="0.01"':'')+' '+(['email','phone','houseNumber','documentNumber','birthDate','documentExpiry','children','taxExemptAdults','taxExemptChildren','depositAmount','depositDue','groupRef','location'].includes(key)?'':'required')+'>';return '<div class="editor-field'+(type==='textarea'?' full-field':'')+'"><label>'+title+'</label>'+field+'</div>'}).join('')+'</div>'+(k==='rooms'?priceForm(x):'')+(k==='bookings'?'<div id="booking-quote-preview" class="pricing-quote">Preisvorschau nach Eingabe verfügbar</div>':'')+'<p id="editor-error" role="alert" hidden></p><div class="actions dialog-actions">'+(id?btn('Löschen','delete',k+':'+id,'danger'):'')+btn('Abbrechen','close')+'<button class="primary" type="submit">Speichern</button></div></form>');
if(k==='bookings'){const updateQuote=()=>{const box=$('booking-quote-preview');if(!box)return;try{const form=$('editor');const o=Object.fromEntries(new FormData(form).entries());const room=get('rooms',o.room);if(!room.id){box.textContent='Zimmer auswählen';return}const isSaved=Boolean(id&&unchangedReservationTariff(x,o));const quote=isSaved?x.priceSnapshot:bookingQuote(o,room,db.hotel);box.innerHTML='<strong>'+(isSaved?'Gespeicherter Preis':'Neue Kalkulation')+' · '+quote.nights+' Nächte</strong><p>'+quote.adults+' Erwachsene · '+quote.children+' Kinder</p><p>Zimmer ohne Verpflegung: '+money(quote.lodging)+'</p><p>Frühstück (3.8 % MWST): '+money(quote.breakfast)+'</p><p>Weitere Mahlzeiten (8.1 % MWST): '+money(quote.other)+'</p><p>Kurtaxe / Gästetaxe: '+money(quote.touristTax||0)+'</p><strong>Gesamt: '+money(quote.total)+'</strong>'}catch(e){box.textContent='Preisvorschau: '+e.message}};$('editor').addEventListener('input',updateQuote);$('editor').addEventListener('change',updateQuote);updateQuote()}
$('editor').addEventListener('invalid',e=>{const field=e.target;const label=field.previousElementSibling;const box=$('editor-error');if(box){box.hidden=false;box.textContent='Bitte prüfen: '+(label?.textContent||field.name)+' – '+field.validationMessage}},true);$('editor').onsubmit=e=>{e.preventDefault();const n={};new FormData(e.target).forEach((v,k)=>n[k]=v);n.id=id||uid();if(k==='guests'){n.address=formattedAddress(n);if(n.birthDate&&n.birthDate>today())throw Error('Geburtsdatum liegt in der Zukunft');if(n.documentExpiry&&n.birthDate&&n.documentExpiry<n.birthDate)throw Error('Ungültiges Ablaufdatum')}try{if(k==='maintenance'&&!get('rooms',n.room).id)throw Error('Bitte Zimmer auswählen');if(k==='guestWishes'){if(!get('guests',n.guest).id||!get('rooms',n.room).id)throw Error('Bitte Gast und Zimmer auswählen');n.location=get('guests',n.guest).name+' · Zimmer '+get('rooms',n.room).number}if(k==='bookings'){if(!get('guests',n.guest).id||!get('rooms',n.room).id)throw Error('Bitte Gast und Zimmer auswählen');const occ=occupancy(n);n.people=String(occ.people);const tariffUnchanged=Boolean(id&&unchangedReservationTariff(x,n));const q=tariffUnchanged?x.priceSnapshot:bookingQuote(n,get('rooms',n.room),db.hotel);n.priceSnapshot=q;n.groupRef=String(n.groupRef||'').trim();if(n.groupRef.length>80)throw Error('Gruppenreferenz zu lang');const deposit=Number(n.depositAmount||0);if(!Number.isFinite(deposit)||deposit<0||cents(deposit)>cents(q.total)||deposit>0&&!n.depositDue)throw Error('Anzahlung muss zwischen null und dem Gesamtbetrag liegen und benötigt ein Fälligkeitsdatum');if(nights(n)<=0)throw Error('Aufenthalt ungültig');if(active(n)&&(get('rooms',n.room).status==='Gesperrt'||db.bookings.some(b=>b.id!==n.id&&b.room===n.room&&active(b)&&overlap(b,n))))throw Error('Zimmer nicht verfügbar: Doppelbuchung');if(id&&db.invoices.some(i=>i.booking===id))throw Error('Reservation bereits abgerechnet. Änderungen an abgerechneten Reservationen sind gesperrt.')}if(k==='services'){if(!get('bookings',n.booking).id||!Number.isFinite(Number(n.amount))||Number(n.amount)<=0)throw Error('Zusatzleistung ungültig');if(db.invoices.some(i=>i.booking===n.booking||i.booking===x.booking))throw Error('Reservation bereits abgerechnet')}if(k==='payments'){const inv=get('invoices',n.invoice);if(!inv.id||!Number.isFinite(Number(n.amount))||Number(n.amount)<=0||Number(n.amount)>inv.total-paid(inv.id)-credited(inv.id)+(x.invoice===n.invoice?Number(x.amount)||0:0)+0.00001)throw Error('Zahlungsbetrag ungültig')}if(k==='rooms')validPricePlan(n);if(k==='rooms'&&!ROOM_CATEGORIES.includes(n.category)&&(!id||n.category!==x.category))throw Error('Bitte eine gültige Zimmerkategorie auswählen');if(k==='rooms'&&db.rooms.some(r=>r.id!==n.id&&r.number===n.number))throw Error('Zimmernummer bereits vorhanden');if(k==='bookings'&&id&&x.status!==n.status&&['Eingecheckt','Ausgecheckt'].includes(n.status))throw Error('Bitte Check-in / Check-out verwenden');if(k==='bookings'&&!id&&['Eingecheckt','Ausgecheckt'].includes(n.status))throw Error('Bitte zuerst Reservation bestätigen');atomicChange(()=>{db[k]=db[k].filter(r=>r.id!==n.id).concat(Object.assign({},x,n));if(k==='tasks'&&n.name==='Abreisereinigung'&&n.status==='Erledigt'&&!db.tasks.some(t=>t.room===n.room&&t.status==='Offen')){const room=get('rooms',n.room);if(room.status==='Reinigung')room.status='Bereit'}},schema[0]+' gespeichert');close();render()}catch(err){alert(err.message)}}}
