function creditNew(id){const x=get('invoices',id);const remaining=Math.round((x.total-credited(id))*100)/100;if(!x.id||remaining<=0)throw Error('Kein verbleibender Rechnungsbetrag für Gutschrift');dialog('<h2>Gutschrift erstellen</h2><p>Maximal '+money(remaining)+'</p><form id="credit-form"><label>Rechnungsposition</label><select name="line">'+x.lines.map((l,i)=>'<option value="'+i+'">'+esc(l.name)+' · '+money(l.amount)+'</option>').join('')+'</select><label>Betrag inklusive MWST</label><input name="amount" type="number" min="0.01" max="'+remaining+'" step="0.01" required><label>Begründung</label><textarea name="reason" required></textarea><div class="actions dialog-actions">'+btn('Abbrechen','close')+'<button class="primary" type="submit">Gutschrift speichern</button></div></form>');$('credit-form').onsubmit=e=>{e.preventDefault();try{const f=new FormData(e.target),i=Number(f.get('line')),l=x.lines[i],cents=Math.round(Number(f.get('amount'))*100),reason=String(f.get('reason')).trim(),history=x.credits||[];if(!l||!reason||!Number.isSafeInteger(cents)||cents<=0||cents>Math.round((x.total-credited(id))*100)||cents>Math.round(l.amount*100)-history.filter(c=>c.line===i).reduce((n,c)=>n+Math.round(c.amount*100),0))throw Error('Ungültiger Gutschriftbetrag');const c={number:'GS-'+x.number+'-'+(history.length+1),date:today(),line:i,name:l.name,vat:l.vat,taxTreatment:l.taxTreatment,amount:cents/100,reason};atomicChange(()=>{x.credits=history.concat(c)},'Gutschrift '+c.number+' erstellt');close();creditView(id,history.length)}catch(err){alert(err.message)}}}
