function swissIban(value){const iban=String(value||'').replace(/\s/g,'').toUpperCase();if(!/^(CH|LI)[0-9]{7}[A-Z0-9]{12}$/.test(iban))return false;let rem=0;for(const c of iban.slice(4)+iban.slice(0,4)){for(const digit of (/[A-Z]/.test(c)?String(c.charCodeAt(0)-55):c))rem=(rem*10+Number(digit))%97}return rem===1}
function qrPaymentData(id){const x=get('invoices',id),h=x.issuer||db.hotel,iban=String(h.iban||'').replace(/\s/g,'').toUpperCase(),amount=Math.round((x.total-paid(id)-credited(id))*100)/100;if(!swissIban(iban))throw Error('Gültige Schweizer oder Liechtensteiner IBAN erforderlich');if(Number(iban.slice(4,9))>=30000&&Number(iban.slice(4,9))<=31999)throw Error('QR-IBAN benötigt eine QR-Referenz; derzeit nur normale IBAN unterstützt');if(!Number.isFinite(amount)||amount<=0||amount>999999999.99)throw Error('Ungültiger offener Betrag');if(![h.name,h.postalCode,h.city,h.street].every(v=>String(v||'').trim()))throw Error('Strukturierte Hoteladresse in Einstellungen erforderlich');const clean=(v,max)=>{const t=String(v||'').trim();if(/[\r\n]/.test(t)||t.length>max)throw Error('Adressfeld oder Referenz ungültig');return t};const country=h.country||'CH';if(!/^[A-Z]{2}$/.test(country))throw Error('Ländercode ungültig');return ['SPC','0200','1',iban,'S',clean(h.name,70),clean(h.street,70),clean(h.houseNumber,16),clean(h.postalCode,16),clean(h.city,35),country,'','','','','','','',amount.toFixed(2),'CHF','','','','','','','','NON','',clean(x.number,140),'EPD'].join('\r\n')}
