function invoiceDue(day){const d=new Date(day+'T12:00:00');d.setDate(d.getDate()+30);return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')}
function invoiceTax(lines){const groups={};lines.filter(l=>l.taxTreatment!=='pass_through').forEach(l=>{const rate=Number(l.vat),gross=Math.round(Number(l.amount)*100);groups[rate]=(groups[rate]||0)+gross});return Object.keys(groups).map(k=>{const gross=groups[k],tax=Math.round(gross*Number(k)/(100+Number(k)));return {rate:Number(k),gross:gross/100,net:(gross-tax)/100,tax:tax/100}}).sort((a,b)=>a.rate-b.rate)}
function refundNew(id){const inv=get('invoices',id),limit=cents(paid(id))+cents(credited(id))-cents(inv.total);if(!inv.id||limit<=0)throw Error('Keine rückzahlbare Überzahlung vorhanden');dialog('<h2>Rückerstattung erfassen</h2><p>Nur bereits ausgeführte Rückzahlungen dokumentieren. Maximal '+money(chf(limit))+'</p><form id="refund-form"><label>Betrag CHF</label><input name="amount" type="number" min="0.01" max="'+chf(limit)+'" step="0.01" required><label>Auszahlungsdatum</label><input name="date" type="date" max="'+today()+'" value="'+today()+'" required><label>Zahlungsart</label><select name="method"><option>Banküberweisung</option><option>Bar</option><option>Karte</option><option>TWINT</option></select><label>Zahlungsnachweis / Referenz</label><input name="reference" required><label>Begründung</label><textarea name="reason" required></textarea><div class="actions"><button type="submit">Rückzahlung speichern</button>'+btn('Abbrechen','close')+'</div></form>');$('refund-form').onsubmit=e=>{e.preventDefault();try{const v=Object.fromEntries(new FormData(e.target).entries()),amount=cents(v.amount),max=cents(paid(id))+cents(credited(id))-cents(inv.total);if(!Number.isSafeInteger(amount)||amount<=0||amount>max||!v.date||v.date>today()||!v.reference.trim()||!v.reason.trim())throw Error('Ungültige Rückzahlung');const history=inv.refunds||[],r={...v,amount:chf(amount),number:'RS-'+inv.number+'-'+(history.length+1)};atomicChange(()=>{inv.refunds=history.concat(r)},'Rückerstattung '+r.number+' erfasst');close();documentPreview('ruckerstattungsbeleg',id+':'+history.length)}catch(err){alert(err.message)}}}
function invoice(id){const x=get('invoices',id);if(!x.id)throw Error('Rechnung nicht gefunden');const tax=invoiceTax(x.lines),issuer=x.issuer||db.hotel,net=cents(x.total)-tax.reduce((n,t)=>n+cents(t.tax),0),balance=cents(x.total)-cents(paid(id))-cents(credited(id));close();documentZoom=100;documentReturnPage=page;documentLast={id:'rechnung',day:x.date,columns:['Leistung','Menge','Einzelpreis CHF','MWST','Brutto CHF'],rows:x.lines.map(l=>[l.name,l.quantity||1,Number(l.amount/(l.quantity||1)).toFixed(2),l.taxTreatment==='pass_through'?'–':l.vat+' %',Number(l.amount).toFixed(2)])};document.body.classList.remove('reference-dashboard');document.body.classList.add('document-preview');const meta=(k,v)=>'<dt>'+esc(k)+'</dt><dd>'+esc(v||'–')+'</dd>',sum=(k,v)=>'<div><span>'+esc(k)+'</span><strong>'+money(v)+'</strong></div>';$('main').innerHTML='<div class="pdf-preview-toolbar no-print"><strong>PDF-Vorschau · '+esc(x.number)+'</strong><div class="actions">'+btn('−','documentZoomOut')+btn('100 %','documentZoomReset')+btn('+','documentZoomIn')+btn('PDF / Drucken','print')+btn('CSV teilen','documentCsv')+btn('Schliessen','documentClose')+'</div></div><article class="report-a4 invoice-report"><div class="report-topline"></div><header class="invoice-letterhead"><div class="invoice-brand"><svg width="50" height="50" viewBox="0 0 50 50"><rect x="1" y="4" width="44" height="44" rx="11" fill="#dceafa"/><path d="M10 38V13H17V23H28V13H35V38H28V30H17V38Z" fill="#284a6b"/><rect x="33" y="1" width="15" height="15" rx="4" fill="#dc3545"/><path d="M40.5 4v9m-4.5-4.5h9" stroke="white" stroke-width="2"/></svg><div><strong>STAY Swiss</strong><small>HOTEL MANAGEMENT</small></div></div><div class="invoice-issuer"><strong>'+esc(issuer.name)+'</strong><div>'+esc(issuer.address||formattedAddress(issuer))+'</div><div>'+esc(issuer.vat||'')+'</div><div>'+esc([issuer.email,issuer.phone].filter(Boolean).join(' · '))+'</div></div></header><h1>Gastrechnung</h1><dl class="invoice-meta">'+meta('Rechnungsnummer',x.number)+meta('Gast',[x.guest,x.guestAddress].filter(Boolean).join(', '))+meta('Aufenthalt',(x.arrival||'–')+' – '+(x.departure||'–')+' · Zimmer '+(x.roomNumber||'–'))+meta('Rechnungsdatum',x.date)+meta('Fällig',x.dueDate)+'</dl>'+htmlTable(documentLast.columns,documentLast.rows)+'<div class="invoice-bottom"><div><h3>Hinweise</h3><p>Währung: CHF</p><p>IBAN: '+esc(issuer.iban||'–')+'</p><p>Zahlungsreferenz: '+esc(x.number)+'</p></div><div class="invoice-totals">'+sum('Netto inkl. separater Abgaben',chf(net))+tax.map(t=>sum('MWST '+t.rate+' %',t.tax)).join('')+sum('Brutto',x.total)+sum('Bezahlt',paid(id))+(credited(id)?sum('Gutschriften',credited(id)):'')+sum(balance<0?'Überzahlung':'Offen',chf(Math.abs(balance)))+'</div></div><footer class="report-footer">'+esc(issuer.name)+' · STAY Swiss</footer></article><div class="actions no-print invoice-management">'+btn('PDF / Drucken','print')+(x.total-paid(id)-credited(id)>0?btn('QR-Zahlungsdaten','qrData',id):'')+(cents(x.total)>cents(credited(id))?btn('Gutschrift erstellen','creditNew',id):'')+(x.credits||[]).map((c,i)=>btn(c.number,'creditView',id+':'+i)).join('')+(paid(id)+credited(id)>x.total?btn('Rückerstattung erfassen','refundNew',id):'')+(x.refunds||[]).map((r,i)=>btn(r.number,'refundView',id+':'+i)).join('')+((x.reminders||[]).length?btn('Letzte Mahnung','showReminder',id):'')+(x.dueDate&&x.dueDate<today()&&Math.round((x.total-paid(id)-credited(id))*100)>0?btn('Mahnung erstellen','reminder',id):'')+(x.total-paid(id)-credited(id)>0?btn('Zahlung erfassen','invoicePayment',id):'')+'</div>'}

document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;e.preventDefault();const a=b.dataset.action,id=b.dataset.id;try{if(a==='go'){close();navigate(id)}else if(a==='documentSection'){if(DOCUMENT_TYPES.some(x=>x.section===id)){documentSection=id;render()}}else if(a==='listPage'){listPage=Number(id)||1;if($('results')&&schemas[page])$('results').innerHTML=list(page)}else if(a==='tab'){tab=id;render()}else if(a==='roomTariff')showRoomTariff(id);else if(a==='edit'){const [k,i]=id.split(':');edit(k,i)}else if(a==='receptionFilter'){receptionFilter=id;query='';render()}else if(a==='reception')receptionAction(id);else if(a==='stayTransition'){const parts=id.split(':');transitionStay(parts[0],parts[1])}else if(a==='receptionSearch'){query=$('reception-search').value;close();render()}else if(a==='mealPrint')mealPrint(mealPlan(mealDay));else if(a==='mealDate')selectMealDay();else if(a==='mealCsv')mealExport(mealPlan(mealDay));else if(a==='close')close();else if(a==='delete'){const [k,i]=id.split(':');if(k==='payments'||k==='bookings'&&db.invoices.some(x=>x.booking===i)||k==='guests'&&(db.bookings.some(x=>x.guest===i)||db.guestWishes.some(x=>x.guest===i))||k==='rooms'&&(db.bookings.some(x=>x.room===i)||db.tasks.some(x=>x.room===i)||db.maintenance.some(x=>x.room===i)||db.guestWishes.some(x=>x.room===i))||k==='services'&&db.invoices.some(x=>x.booking===get(k,i).booking))throw Error('Verknüpfte oder finanzielle Daten dürfen nicht gelöscht werden');if(confirm('Eintrag löschen?')){db[k]=db[k].filter(x=>x.id!==i);log('Eintrag gelöscht');close();render()}}else if(a==='invoiceNew')invoiceNew();else if(a==='invoiceCreate'){const b=get('bookings',$('billBooking').value);if(!b.id)throw Error('Reservation auswählen');const isSnapshot=Boolean(b.priceSnapshot&&Number.isFinite(Number(b.priceSnapshot.lodging)));const q=isSnapshot?b.priceSnapshot:((rate)=>({nights:nights(b),adults:Number(b.people||1),children:0,lodging:chf(cents(nights(b)*rate)),breakfast:0,other:0}))(Number(b.rate==null?get('rooms',b.room).rate:b.rate));const lines=[{name:q.nights+' Übernachtungen'+(isSnapshot?' · '+q.adults+' Erw. / '+q.children+' Kinder':''),vat:VAT_LODGING,quantity:q.nights,amount:q.lodging}];if(q.breakfast>0)lines.push({name:'Frühstück · '+q.nights+' Nächte',vat:VAT_LODGING,amount:q.breakfast});if(q.other>0)lines.push({name:(b.meal==='Vollpension'?'Mittag- und Abendessen':'Zusätzliche Mahlzeit')+' · '+q.nights+' Nächte',vat:VAT_CATERING,amount:q.other});if(Number(q.touristTax||0)>0)lines.push({name:'Kurtaxe / Gästetaxe · '+q.nights+' Nächte (separat)',vat:0,taxTreatment:'pass_through',amount:Number(q.touristTax)});lines.push(...db.services.filter(s=>s.booking===b.id).map(s=>({name:s.name,vat:Number(s.vat),amount:Number(s.amount)})));const x={id:uid(),number:'RE-'+new Date().getFullYear()+'-'+String(db.invoices.length+1).padStart(4,'0'),booking:b.id,guest:get('guests',b.guest).name,guestAddress:formattedAddress(get('guests',b.guest)),issuer:Object.assign({},db.hotel),arrival:b.arrival,departure:b.departure,roomNumber:get('rooms',b.room).number,date:today(),dueDate:invoiceDue(today()),lines,total:Math.round(lines.reduce((s,l)=>s+l.amount,0)*100)/100};atomicChange(()=>{if(db.invoices.some(i=>i.booking===b.id)||['Storniert','Anfrage'].includes(b.status))throw Error('Reservation nicht abrechenbar');if(!Number.isFinite(x.total)||x.total<0||lines.some(l=>!Number.isFinite(l.amount)||l.amount<0||![0,2.6,3.8,8.1].includes(Number(l.vat))))throw Error('Ungültige Rechnungsposition');db.invoices.push(x)},'Rechnung erstellt');invoice(x.id)}else if(a==='qrData')qrDataView(id);else if(a==='refundView')documentPreview('ruckerstattungsbeleg',id);else if(a==='refundNew')refundNew(id);else if(a==='creditNew')creditNew(id);else if(a==='creditView'){const p=id.split(':');creditView(p[0],Number(p[1]))}else if(a==='reminder')reminder(id);else if(a==='showReminder')showReminder(id);else if(a==='invoicePayment'){edit('payments');const field=$('editor').querySelector('[name="invoice"]');field.value=id;const amount=$('editor').querySelector('[name="amount"]');amount.value=Math.max(0,Math.round((get('invoices',id).total-paid(id)-credited(id))*100)/100).toFixed(2)}else if(a==='invoice')invoice(id);else if(a==='mailPreview')previewMail(id);else if(a==='mailCompose'){const recipient=$('mail-to')?.value||'',subject=$('mail-subject')?.value||'',body=$('mail-body')?.value||'';if(recipient&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(recipient))throw Error('Ungültige E-Mail-Adresse');if(typeof Stay!=='undefined'&&typeof Stay.email==='function'){Stay.email(recipient,subject,body)}else if(typeof Stay!=='undefined'){Stay.share('Betreff: '+subject+'\n\n'+body)}else{window.location.href='mailto:'+encodeURIComponent(recipient)+'?subject='+encodeURIComponent(subject)+'&body='+encodeURIComponent(body)}}else if(a==='documentPreview')documentPreview(id);else if(a==='documentZoomIn')changeDocumentZoom(25);else if(a==='documentZoomOut')changeDocumentZoom(-25);else if(a==='documentZoomReset')changeDocumentZoom(0);else if(a==='documentClose')documentClose();else if(a==='documentPickDate')documentPickDate();else if(a==='documentCsv')documentCsv();else if(a==='touristTaxCsv')exportTouristTaxCsv();else if(a==='support'){if(typeof Stay!=='undefined'&&typeof Stay.openExternal==='function')Stay.openExternal('https://buymeacoffee.com/swisstech');else window.open('https://buymeacoffee.com/swisstech','_blank','noopener,noreferrer')}else if(a==='hotelSave'){const changed=Object.assign({},db.hotel);document.querySelectorAll('[data-hotel]').forEach(x=>changed[x.dataset.hotel]=x.value);document.querySelectorAll('.meal-price-settings [name], .tourist-tax-settings [name]').forEach(x=>changed[x.name]=x.value);validateMealPrices(changed);validateTouristTax(changed);changed.address=formattedAddress(changed);db.hotel=changed;log('Hotelprofil und Verpflegungspreise gespeichert');render()}else if(a==='print'){if(typeof Stay!=='undefined')Stay.print();else window.print()}else if(a==='backup'){if(typeof Stay!=='undefined')Stay.share(JSON.stringify(db));else{const l=document.createElement('a');l.href=URL.createObjectURL(new Blob([JSON.stringify(db)],{type:'application/json'}));l.download='stay-backup.json';l.click();URL.revokeObjectURL(l.href)}}}catch(err){alert(err.message)}});
