let receptionFilter='arrivals';
function atomicChange(fn,message){const before=JSON.stringify(db);try{fn();log(message)}catch(e){db=JSON.parse(before);throw e}}
function transitionStay(id,target){const b=get('bookings',id),r=get('rooms',b.room);if(!b.id||!r.id)throw Error('Reservation oder Zimmer fehlt');if(target==='Eingecheckt'){if(b.status!=='Bestätigt'||b.arrival>today()||b.departure<=today())throw Error('Check-in ausserhalb des bestätigten Aufenthalts');if(r.status!=='Bereit'||db.bookings.some(x=>x.id!==id&&x.room===r.id&&x.status==='Eingecheckt'))throw Error('Zimmer ist nicht bezugsbereit')}else if(target==='Ausgecheckt'){if(b.status!=='Eingecheckt')throw Error('Gast ist nicht eingecheckt')}else throw Error('Ungültiger Statuswechsel');atomicChange(()=>{b.status=target;b[target==='Eingecheckt'?'checkedInAt':'checkedOutAt']=new Date().toISOString();if(target==='Ausgecheckt'){r.status='Reinigung';if(!db.tasks.some(t=>t.room===r.id&&t.status==='Offen'&&t.name==='Abreisereinigung'))db.tasks.push({id:uid(),room:r.id,name:'Abreisereinigung',status:'Offen'})}},target+' · '+label('bookings',b));close();render()}
function receptionAction(id){const b=get('bookings',id);if(!b.id)return;const target=b.status==='Eingecheckt'?'Ausgecheckt':'Eingecheckt';dialog('<h2>'+esc(target==='Eingecheckt'?'Check-in':'Check-out')+'</h2><p>'+esc(label('bookings',b))+'</p><p>Zimmer '+esc(get('rooms',b.room).number)+'</p>'+ (target==='Ausgecheckt'?'<p>Zimmer wird zur Reinigung freigegeben. Offene Rechnungen bleiben bestehen.</p>':'')+btn('Abbrechen','close')+btn('Bestätigen','stayTransition',id+':'+target,'primary'))}
function renderReception(){document.body.classList.add('reference-dashboard');$('main').innerHTML=checkinReference;const svg=$('main').querySelector('svg'),m=svg.querySelector('#main-view'),w=svg.querySelector('#workspace-view'),d=today();
 const arrivals=db.bookings.filter(b=>b.status==='Bestätigt'&&b.arrival<=d&&b.departure>d),departures=db.bookings.filter(b=>b.status==='Eingecheckt'&&b.departure<=d),inhouse=db.bookings.filter(b=>b.status==='Eingecheckt'),done=db.bookings.filter(b=>[b.checkedInAt,b.checkedOutAt].some(t=>t&&new Date(t).toLocaleDateString()===new Date().toLocaleDateString()));
 const set=(g,x,y,v)=>{const t=g.querySelector('text[x="'+x+'"][y="'+y+'"]');if(t)t.textContent=v};const bind=bindSvgAction;
 const select=()=>({arrivals,departures,inhouse,done})[receptionFilter].filter(b=>label('bookings',b).toLowerCase().includes(query.toLowerCase()));const rows=select(),shown=rows.slice(0,3);
 const choose=k=>{receptionFilter=k;renderReception()};const listAll=()=>dialog('<h2>Aufenthalte</h2>'+rows.map(b=>entry(label('bookings',b),b.status,'reception',b.id)).join('')+btn('Schliessen','close'));
 const search=()=>{dialog('<h2>Aufenthalte suchen</h2><input id="reception-search" value="'+esc(query)+'">'+btn('Übernehmen','receptionSearch'));};
 [arrivals.length,departures.length,done.length,arrivals.length+departures.length].forEach((v,i)=>set(m,i%2?215:29,i<2?264:348,v));[arrivals.length,departures.length,done.length].forEach((v,i)=>set(w,128+i*112,284,v));for(const g of [m,w])set(g,16,132,new Date().toLocaleDateString('de-CH'));
 set(m,16,492,({arrivals:'Anreisen',departures:'Abreisen',inhouse:'Im Haus',done:'Erledigt'})[receptionFilter]);set(m,194,746,receptionFilter==='arrivals'?'Check-in durchführen':'Aufenthalte anzeigen');set(w,30,726,rows.length+' Einträge');
 for(let i=0;i<3;i++){const b=shown[i],name=b?get('guests',b.guest).name:'Keine weiteren Einträge',desc=b?'Zimmer '+get('rooms',b.room).number+' · '+b.people+' Personen · '+b.status:'';set(m,71,530+i*69,name);set(m,71,548+i*69,desc);set(w,29,503+i*68,name);set(w,29,522+i*68,desc)}
 const routes={'01-dashboard.svg':'dashboard','06-kalender.svg':'calendar','03-buchungen.svg':'bookings','09-rechnungen.svg':'invoices','19-menu.svg':'more','22-systemmeldungen.svg':'logs'};let q=0;svg.querySelectorAll('a').forEach(a=>{const t=(a.querySelector('title')||{}).textContent,h=a.getAttribute('href');bind(a,()=>{if(t==='Check-in durchführen')listAll();else if(h==='#main-view'||h==='#workspace-view'){tab=h==='#main-view'?'overview':'work';renderReception()}else if(routes[h])navigate(routes[h]);else if(h==='08-suche.svg')$('search').click();else if(h==='20-pdf-vollbild.svg'){if(typeof Stay!=='undefined')Stay.print();else window.print()}else if(t.indexOf('Schnellzugriff')===0)choose(['arrivals','departures','done'][q++%3]);else search()})});
 m.querySelectorAll('g[tabindex]').forEach((g,i)=>bind(g,()=>{if(shown[i])receptionAction(shown[i].id)}));w.querySelectorAll('g[tabindex]').forEach((g,i)=>bind(g,()=>{if(i<2)search();else if(shown[Math.floor((i-2)/2)])receptionAction(shown[Math.floor((i-2)/2)].id)}));
 [64.5,177.5,298.5].forEach((x,i)=>bind(m.querySelector('text[x="'+x+'"][y="401"]'),()=>choose(['arrivals','departures','inhouse'][i])));bind(m.querySelector('text[x="373"][y="491"]'),listAll);bind(m.querySelector('text[x="59"][y="448"]'),search);bind(w.querySelector('text[x="55"][y="410"]'),search);bind(w.querySelector('text[x="331"][y="736"]'),()=>{const csv=rows.map(b=>[b.id,b.arrival,b.departure,b.status].join(';')).join('\n');if(typeof Stay!=='undefined')Stay.share(csv)});m.setAttribute('display',tab==='work'?'none':'inline');w.setAttribute('display',tab==='work'?'inline':'none')}


