let mealFilter='',mealOffset=0,mealDay=today();
function selectMealDay(){dialog('<h2>Verpflegungsdatum</h2><label>Datum</label><input id="meal-day" type="date" value="'+esc(mealDay)+'">'+btn('Schliessen','close'));$('meal-day').onchange=e=>{if(!e.target.value)return;mealDay=e.target.value;mealOffset=0;close();render()}}
function mealPrint(rows,day=mealDay){const keys=['breakfast','lunch','dinner'],people=x=>Number(x.booking.people)||0,totals=keys.map(k=>rows.reduce((n,x)=>n+(x[k]?people(x):0),0)),tariffs=['Nur Logis','Frühstück','Halbpension','Vollpension'];documentZoom=100;documentReturnPage=page;documentLast={id:'verpflegungsplan',day,columns:['Zimmer','Gast','Tarif','Pers.','F','M','A'],rows:rows.map(x=>[get('rooms',x.booking.room).number,get('guests',x.booking.guest).name,x.booking.meal,people(x),...keys.map(k=>x[k]?people(x):'–')])};document.body.classList.remove('reference-dashboard');document.body.classList.add('document-preview');$('main').innerHTML='<div class="pdf-preview-toolbar no-print"><strong>PDF-Vorschau · Täglicher Verpflegungsplan</strong><div class="actions">'+btn('−','documentZoomOut')+btn('100 %','documentZoomReset')+btn('+','documentZoomIn')+btn('PDF / Drucken','print')+btn('CSV teilen','documentCsv')+btn('Schliessen','documentClose')+'</div></div><article class="report-a4 meal-report"><div class="report-topline"></div><h2>STAY Swiss · '+esc(db.hotel.name)+'</h2><h1>Täglicher Verpflegungsplan</h1><p>'+esc(day.split('-').reverse().join('.'))+' · '+rows.reduce((n,x)=>n+people(x),0)+' Gäste · Tagesplanung</p><div class="meal-report-summary">Frühstück: '+totals[0]+'　 Mittagessen: '+totals[1]+'　 Abendessen: '+totals[2]+'</div>'+htmlTable(documentLast.columns,documentLast.rows)+'<p class="meal-report-tariffs">'+tariffs.map(t=>esc(t)+': '+rows.filter(x=>x.booking.meal===t).reduce((n,x)=>n+people(x),0)).join(' · ')+'</p><p>Zusatzmahlzeiten: nicht in diesem Plan erfasst · An-/Abreise: separat prüfen</p><footer class="report-footer">STAY Swiss · '+esc(day)+'</footer></article>';}
function mealExport(rows){const safe=v=>{let t=String(v==null?'':v);if(/^[=+@\-\t\r]/.test(t))t="'"+t;return '"'+t.replace(/"/g,'""')+'"'};const data=[['Datum','Zimmer','Gast','Personen','Frühstück','Mittagessen','Abendessen']].concat(rows.map(x=>[mealDay,get('rooms',x.booking.room).number,get('guests',x.booking.guest).name,x.booking.people,...['breakfast','lunch','dinner'].map(k=>x[k]?x.booking.people:0)])).map(r=>r.map(safe).join(';')).join('\r\n');if(typeof Stay!=='undefined'&&typeof Stay.shareCsv==='function')Stay.shareCsv('verpflegung-'+mealDay+'.csv','\ufeff'+data);else if(typeof Stay!=='undefined')Stay.share(data);else{const url=URL.createObjectURL(new Blob(['\ufeff',data],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='verpflegung-'+mealDay+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}}
