 const desc=x=>x.booking.meal+' · '+x.booking.people+' Pers.';
 const rows=plan.filter(x=>(!mealFilter||x[mealFilter])&&(title(x)+' '+desc(x)).toLowerCase().includes(query.toLowerCase()));
 const size=tab==='work'?3:7;if(mealOffset>=rows.length)mealOffset=0;const shown=rows.slice(mealOffset,mealOffset+size);
