 keys.forEach((k,i)=>{set(m,74+i*121,204,count(k));set(w,40+i*110,316,count(k)+' '+names[i]);bind(m.querySelector('text[x="'+(74+i*121)+'"][y="204"]'),()=>choose(k))});
